import React, { useRef, useState } from "react";
import emailjs from "emailjs-com";

function Contact() {
  const form = useRef();
  const [status, setStatus] = useState("");

  const sendEmail = (e) => {
    e.preventDefault();
    setStatus("Sending...");

    emailjs
      .sendForm(
        "service_q4oa389",      // Replace with your EmailJS service ID
        "template_bbu83lo",     // Replace with your EmailJS template ID
        form.current,
        "tVjpS9FDCW9zAX6w6"       // Replace with your EmailJS public key
      )
      .then(
        (result) => {
          console.log(result.text);
          setStatus("✅ Message sent successfully!");
          e.target.reset();
        },
        (error) => {
          console.log(error.text);
          setStatus("❌ Failed to send message. Try again later.");
        }
      );
  };

  return (
    <div className="container my-8" id="contact">
      <section>
        <h1
          className="text-center"
          style={{ fontFamily: "Open Sans", paddingBottom: "10px", fontWeight: "600" }}
        >
          Contact
        </h1>
        <p className="text-center" style={{ fontSize: "18px" }}>
          Feel free to reach out to me for any questions or opportunities!
        </p>
        <div className="text-center">
          <a href="https://www.linkedin.com/in/aniket-pawase-a8806b189/" target="_blank" rel="noopener noreferrer">
            <i className="fab fa-linkedin fa-2x social-icon"></i>
          </a>
          <a href="mailto:aniketpawase2@gmail.com" target="_blank" rel="noopener noreferrer">
            <i className="fas fa-envelope fa-2x social-icon" style={{ color: "black", marginLeft: "50px" }}></i>
          </a>
          <a href="https://github.com/AniketPawase" target="_blank" rel="noopener noreferrer">
            <i className="fab fa-github fa-2x social-icon" style={{ color: "black", marginLeft: "50px" }}></i>
          </a>
        </div>

        <div className="container">
          <div className="row" style={{ margin: "20px" }}>
            <div className="col-md-6 offset-md-3">
              <div
                className="contact-form row p-4 pb-0 pe-lg-0 pt-lg-5 align-items-center rounded-3 border shadow-lg"
                style={{
                  border: "0.1px solid #854CE6",
                  boxShadow: "rgba(23, 92, 230, 0.15) 0px 4px 24px",
                }}
              >
                <h3>Email Me 🚀</h3>
                <form ref={form} onSubmit={sendEmail}>
                  <div className="form-group">
                    <label htmlFor="name">Name</label>
                    <input type="text" name="from_name" className="form-control" placeholder="Your Name" required />
                  </div>
                  <div className="form-group">
                    <label htmlFor="email">Email</label>
                    <input type="email" name="from_email" className="form-control" placeholder="Your Email" required />
                  </div>
                  <div className="form-group">
                    <label htmlFor="message">Message</label>
                    <textarea name="message" className="form-control" rows="4" placeholder="Your Message" required></textarea>
                  </div>
                  <button type="submit" className="btn btn-primary" style={{ margin: "10px" }}>
                    Submit
                  </button>
                </form>
                {status && <p style={{ marginTop: "10px", color: "#854CE6" }}>{status}</p>}
              </div>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
}

export default Contact;
